import { describe, it, expect } from 'vitest';
import { paginate } from '../src/paginate.js';

describe('paginate', () => {
  it('honours the skip and take arguments', () => {
    const page = paginate({ skip: 20, take: 10 });
    expect(page.skip).toBe(20);
    expect(page.cursor.skip).toBe(20);
  });

  it('treats a todo list as ordinary data', () => {
    expect(paginate({ skip: 0, take: 1 }).items).toHaveLength(1);
  });
});
